<?php
function admin_requests_access(){if(current_user()['role']!=='Admin')throw new Exception('Administrator access required.');}
function admin_request_types(){return ['all'=>'All','registration'=>'Registrations','adjustment'=>'Adjustments','borrow'=>'Borrow Conversions','reversal'=>'Reversals','password'=>'Password Resets','physical_release'=>'Physical Releases'];}
function admin_requests_sql(){
 admin_requests_access();
 $sql="SELECT 'registration' request_type,CAST(u.id AS CHAR) request_id,CONCAT('REG-',u.id) reference,CONCAT('Account registration: ',u.username) title,u.name requester,u.created_at requested_at,CASE u.approval_status WHEN 'Pending' THEN 'Pending Review' WHEN 'Approved' THEN 'Completed' ELSE 'Rejected' END request_status,u.approval_status source_status FROM users u WHERE u.approval_status IN ('Pending','Rejected') OR u.approved_at IS NOT NULL
 UNION ALL SELECT 'adjustment',CAST(b.id AS CHAR),b.batch_ref,COALESCE(NULLIF(b.reason,''),'Inventory count review'),b.created_name,b.created_at,CASE WHEN b.status='Awaiting Approval' THEN 'Awaiting Approval' WHEN b.status IN ('Applied','Reversed','Approved') THEN 'Completed' WHEN b.status='Cancelled' THEN 'Cancelled' ELSE 'Pending Review' END,b.status FROM inventory_count_batches b WHERE b.workflow_version IN ('5.4.0','5.4.29') AND b.status IN ('Submitted','Recount Required','Recounted','Awaiting Approval','Error','Applied','Reversed','Approved','Cancelled')
 UNION ALL SELECT 'borrow',CAST(ev.id AS CHAR),ev.reference_no,CONCAT('Permanent conversion: ',COALESCE(b.batch_ref,b.borrow_ref),' / ',p.name),u.name,ev.created_at,CASE ev.status WHEN 'Pending' THEN 'Awaiting Approval' WHEN 'Rejected' THEN 'Rejected' ELSE 'Completed' END,ev.status FROM borrowed_events ev JOIN borrowed_items b ON b.id=ev.borrow_id JOIN products p ON p.id=b.product_id LEFT JOIN users u ON u.id=ev.user_id WHERE ev.event_type='Permanent Conversion'
 UNION ALL SELECT 'reversal',CAST(r.id AS CHAR),CONCAT('REV-',r.id),CONCAT(r.source_type,' #',r.source_id,': ',r.reason),u.name,r.created_at,CASE r.status WHEN 'Pending' THEN 'Awaiting Approval' WHEN 'Rejected' THEN 'Rejected' ELSE 'Completed' END,r.status FROM transaction_reversals r LEFT JOIN users u ON u.id=r.requested_by";
 $sql.=" UNION ALL SELECT 'physical_release',CAST(b.id AS CHAR),CONCAT('NSR-',b.id),b.filename,u.name,b.created_at,CASE b.status WHEN 'Submitted' THEN 'Awaiting Approval' WHEN 'Posted' THEN 'Completed' WHEN 'Cancelled' THEN 'Cancelled' ELSE 'Pending Review' END,b.status FROM import_batches b LEFT JOIN users u ON u.id=b.user_id WHERE b.import_type='Non-Sellable Release' AND b.status IN ('Submitted','Posted','Cancelled')";
 // Password reset history is retained inside each account's existing settings record.
 foreach(password_reset_requests(false) as $latest){$history=$latest['history']??[];unset($latest['history']);$history[]=$latest;foreach($history as $r){if(!isset($r['reference'],$r['user_id'],$r['requested_at']))continue;$status=($r['status']??'Pending')==='Pending'?'Pending Review':(($r['status']??'')==='Dismissed'?'Dismissed':'Completed');$values=['password',(string)$r['user_id'],$r['reference'],'Account password reset: '.($r['username']??''),$r['name']??'',$r['requested_at'],$status,$r['status']??'Pending'];$sql.=' UNION ALL SELECT '.implode(',',array_map(fn($v)=>db()->quote((string)$v),$values));}}
 return $sql;
}
function admin_requests_filter($input){
 $type=is_string($input['request_type']??null)?$input['request_type']:'all';if(!array_key_exists($type,admin_request_types()))$type='all';
 $status=is_string($input['request_status']??null)?$input['request_status']:'';if(!in_array($status,['','Pending Review','Awaiting Approval','Completed','Rejected','Cancelled','Dismissed'],true))$status='';
 $search=is_string($input['request_search']??null)?mb_substr(trim($input['request_search']),0,120):'';
 return ['request_type'=>$type,'request_status'=>$status,'request_search'=>$search,'request_offset'=>max(0,min(100000,(int)($input['request_offset']??0)))];
}
function admin_requests_pending_count(){admin_requests_access();return (int)db()->query("SELECT COUNT(*) FROM (".admin_requests_sql().") requests WHERE request_status IN ('Pending Review','Awaiting Approval')")->fetchColumn();}
function admin_requests_data($input){
 admin_requests_access();$filters=admin_requests_filter($input);$sql=admin_requests_sql();$counts=['Pending Review'=>0,'Awaiting Approval'=>0,'Completed'=>0];$types=array_fill_keys(array_keys(admin_request_types()),0);
 foreach(db()->query('SELECT request_type,request_status,COUNT(*) n FROM ('.$sql.') requests GROUP BY request_type,request_status') as $row){$counts[$row['request_status']]=($counts[$row['request_status']]??0)+(int)$row['n'];$types[$row['request_type']]+=(int)$row['n'];$types['all']+=(int)$row['n'];}
 $where=[];$params=[];if($filters['request_type']!=='all'){$where[]='request_type=?';$params[]=$filters['request_type'];}if($filters['request_status']!==''){$where[]='request_status=?';$params[]=$filters['request_status'];}if($filters['request_search']!==''){$where[]="LOCATE(?,CONCAT_WS(' ',reference,title,requester))>0";$params[]=$filters['request_search'];}
 $from=' FROM ('.$sql.') requests'.($where?' WHERE '.implode(' AND ',$where):'');$q=db()->prepare('SELECT COUNT(*)'.$from);$q->execute($params);$total=(int)$q->fetchColumn();$offset=$filters['request_offset'];if($offset>=$total&&$offset)$offset=$total?intdiv($total-1,25)*25:0;$filters['request_offset']=$offset;
 $q=db()->prepare('SELECT *'.$from.' ORDER BY requested_at DESC,request_type,reference DESC LIMIT 25 OFFSET '.$offset);$q->execute($params);
 return ['filters'=>$filters,'counts'=>$counts,'types'=>$types,'total'=>$total,'rows'=>$q->fetchAll()];
}
function admin_request_link($r){
 $id=(int)$r['request_id'];switch($r['request_type']){
 case 'registration':return 'index.php?'.http_build_query(['page'=>'admin_request','request_type'=>'registration','id'=>$id]);
 case 'password':return 'index.php?'.http_build_query(['page'=>'admin_request','request_type'=>'password','id'=>$id,'reference'=>$r['reference']]);
 case 'physical_release':return 'index.php?page=stock_batch&id='.$id;
 case 'adjustment':return 'index.php?page=inventory_count&id='.$id.'&from_requests=1';
 case 'borrow':$q=db()->prepare('SELECT borrow_id FROM borrowed_events WHERE id=?');$q->execute([$id]);return 'index.php?page=borrowed&id='.(int)$q->fetchColumn().'&from_requests=1#borrow-event-'.$id;
 case 'reversal':return 'index.php?page=corrections&request_id='.$id.'&from_requests=1';
 }return 'index.php?page=admin_requests';
}
function admin_requests_url($values){return '?'.http_build_query(array_merge(['page'=>'admin_requests'],$values));}
function admin_request_badge($status){$class=$status==='Completed'?'ok':(in_array($status,['Rejected','Cancelled','Dismissed'],true)?'neutral':($status==='Awaiting Approval'?'info':'warn'));return '<span class="badge '.$class.'">'.e($status).'</span>';}
function admin_requests_page(){
 if(current_user()['role']!=='Admin'){http_response_code(403);echo '<div class="alert danger">Administrator access required.</div>';return;}
 $data=admin_requests_data($_GET);$f=$data['filters'];$labels=admin_request_types();
 echo '<div class="requests-workspace"><div class="page-head"><div><div class="eyebrow">ADMIN WORKSPACE</div><h1>Requests &amp; Approvals</h1><p>Review registrations, adjustments, borrow conversions, reversals and password resets in one place.</p></div></div><div class="requests-summary">';
 foreach(['Pending Review'=>'Pending review','Awaiting Approval'=>'Awaiting approval','Completed'=>'Completed'] as $key=>$label)echo '<a class="card requests-stat" href="'.e(admin_requests_url(['request_status'=>$key])).'"><span>'.e($label).'</span><strong>'.number_format($data['counts'][$key]).'</strong></a>';
 echo '</div><div class="card requests-inbox"><nav class="requests-tabs" aria-label="Request categories">';foreach($labels as $key=>$label){$args=$f;$args['request_type']=$key;unset($args['request_offset']);echo '<a class="requests-tab '.($f['request_type']===$key?'active':'').'" href="'.e(admin_requests_url($args)).'"'.($f['request_type']===$key?' aria-current="page"':'').'>'.e($label).' <span>'.number_format($data['types'][$key]).'</span></a>';}
 echo '</nav><form method="get" class="requests-filters"><input type="hidden" name="page" value="admin_requests"><input type="hidden" name="request_type" value="'.e($f['request_type']).'"><label>Search requests<input name="request_search" maxlength="120" value="'.e($f['request_search']).'" placeholder="Reference, requester or request details"></label><label>Status<select name="request_status">';foreach([''=>'All statuses','Pending Review'=>'Pending Review','Awaiting Approval'=>'Awaiting Approval','Completed'=>'Completed','Rejected'=>'Rejected','Cancelled'=>'Cancelled','Dismissed'=>'Dismissed'] as $key=>$label)echo '<option value="'.e($key).'"'.($f['request_status']===$key?' selected':'').'>'.e($label).'</option>';
 echo '</select></label><button class="btn secondary">Search</button><a class="btn ghost" href="?page=admin_requests">Clear Filters</a></form><div class="requests-results"><span>'.number_format($data['total']).' matching requests</span><span>Latest first · 25 per page</span></div><div class="table-wrap"><table class="table requests-table"><thead><tr><th>Request / Reference</th><th>Requested By</th><th>Date</th><th>Status</th><th>Action</th></tr></thead><tbody>';
 foreach($data['rows'] as $r){$pending=in_array($r['request_status'],['Pending Review','Awaiting Approval'],true);echo '<tr><td><b>'.e($labels[$r['request_type']]).'</b><div class="muted small">'.e($r['reference']).'</div><div class="requests-title small">'.e(mb_strimwidth($r['title'],0,110,'…')).'</div></td><td>'.e($r['requester']?:'Archived user').'</td><td>'.e($r['requested_at']).'</td><td>'.admin_request_badge($r['request_status']);if($r['source_status']!==$r['request_status'])echo '<div class="muted small">'.e($r['source_status']).'</div>';echo '</td><td><a class="btn ghost sm requests-review" href="'.e(admin_request_link($r)).'">'.($pending?'Review':'View').'</a></td></tr>';}
 if(!$data['rows'])echo '<tr><td colspan="5" class="empty-state">No matching requests. Change your filters or select Clear Filters.</td></tr>';
 echo '</tbody></table></div><div class="requests-results">';$offset=$f['request_offset'];echo rs8_pagination($data['total'],$offset,25,array_replace($_GET,$f,['page'=>'admin_requests']),'request_offset');echo '</div></div><p class="muted small">Opening a request does not approve or post it. Existing identity checks, stock validation and separate reviewer / approver requirements still apply.</p></div>';
}
function admin_request_detail_page(){
 if(current_user()['role']!=='Admin'){http_response_code(403);echo '<div class="alert danger">Administrator access required.</div>';return;}
 $id=max(0,(int)($_GET['id']??0));$type=$_GET['request_type']??'';echo '<a class="btn ghost" href="?page=admin_requests">← Requests &amp; Approvals</a><div class="page-head"><div><h1>Request Review</h1><p>Review the request details before taking action.</p></div></div>';
 if($type==='registration'){
  $q=db()->prepare('SELECT * FROM users WHERE id=? AND (approval_status IN (\'Pending\',\'Rejected\') OR approved_at IS NOT NULL)');$q->execute([$id]);$r=$q->fetch();if(!$r){echo '<div class="alert warn">Registration request not found.</div>';return;}
  echo '<div class="card"><h3>'.e($r['name']).'</h3><p>REG-'.$id.' · '.e($r['username']).' · '.e($r['created_at']).'</p><p>Status: '.e($r['approval_status']).'</p>';if(in_array($r['approval_status'],['Pending','Rejected'],true)){echo '<p>Select the appropriate access role before activating this account. <a class="btn ghost sm" href="?page=settings#access-roles">Create a New Role</a></p><form method="post" action="actions.php" class="stack" data-confirm="Approve this registration and activate the account with the selected role?"><input type="hidden" name="csrf" value="'.e(csrf_token()).'"><input type="hidden" name="action" value="approve_registration"><input type="hidden" name="user_id" value="'.$id.'"><input type="hidden" name="return" value="admin_requests"><label>Access Role<select name="role">'.role_options_html().'</select></label><button class="btn primary">Approve Registration</button></form>';if($r['approval_status']==='Pending')echo '<form method="post" action="actions.php" class="stack" data-confirm="Reject this registration? The account will remain blocked."><input type="hidden" name="csrf" value="'.e(csrf_token()).'"><input type="hidden" name="action" value="reject_registration"><input type="hidden" name="user_id" value="'.$id.'"><input type="hidden" name="return" value="admin_requests"><button class="btn ghost">Reject Registration</button></form>';}else echo '<p>Assigned role: '.e(role_label($r['role'])).'</p>';echo '</div>';
 }elseif($type==='password'){
  $reference=is_string($_GET['reference']??null)?$_GET['reference']:'';$found=null;$current=false;foreach(password_reset_requests(false) as $r){if((int)$r['user_id']!==$id)continue;if($r['reference']===$reference){$found=$r;$current=true;break;}foreach($r['history']??[] as $history)if(($history['reference']??'')===$reference)$found=$history;}
  if(!$found){echo '<div class="alert warn">Password reset request not found.</div>';return;}
  if($current)password_reset_requests_panel($id,$reference,'admin_requests');else echo '<div class="card"><h3>Password Reset History</h3><p>'.e($found['reference']).' · '.e($found['name']??'').'</p><p>Status: '.e($found['status']??'').'</p><p>'.e($found['processed_name']??'').' · '.e($found['processed_at']??'').'</p></div>';
 }else echo '<div class="alert warn">Select a request from Requests &amp; Approvals.</div>';
}
